BUNDLE_SHA256 = "6a2952b4111788a129ac2eb5fe012a82d449d4fe9b51359869850a9505bc3ed5"
ROOT_PREFIX = "skills-main/"


def main() -> int:
    parser = argparse.ArgumentParser(description="Rebuild the embedded Hugging Face Skills repository.")
    parser.add_argument("destination", nargs="?", help="New output folder (default: ./skills-main-rebuilt)")
    args = parser.parse_args()

    output = Path(args.destination).expanduser() if args.destination else Path(__file__).resolve().parent / "skills-main-rebuilt"
    output = output.resolve()
    script_dir = Path(__file__).resolve().parent
    # Do not write into the directory that contains this script itself.
    if output == script_dir:
        print("Error: choose a separate output directory so existing files are not overwritten.", file=sys.stderr)
        return 2
    if output.exists() and (not output.is_dir() or any(output.iterdir())):
        print(f"Error: destination already exists and is not empty: {output}", file=sys.stderr)
        print("Choose a new destination folder; nothing was overwritten.", file=sys.stderr)
        return 2

    archive_bytes = base64.b64decode("".join(BUNDLE_B64.split()), validate=True)
    import hashlib
    if hashlib.sha256(archive_bytes).hexdigest() != BUNDLE_SHA256:
        print("Error: embedded archive checksum did not match.", file=sys.stderr)
        return 3

    try:
        with zipfile.ZipFile(io.BytesIO(archive_bytes), "r") as archive:
            entries = archive.infolist()
            # Validate every entry before writing anything.
            planned = []
            for entry in entries:
                raw_name = entry.filename
                if not raw_name.startswith(ROOT_PREFIX):
                    raise ValueError(f"Unexpected path outside {ROOT_PREFIX}: {raw_name}")
                relative = raw_name[len(ROOT_PREFIX):]
                if not relative:
                    continue
                part = PurePosixPath(relative)
                if part.is_absolute() or ".." in part.parts or "\\" in relative:
                    raise ValueError(f"Unsafe archive path: {raw_name}")
                unix_mode = (entry.external_attr >> 16) & 0o170000
                if unix_mode == 0o120000:
                    raise ValueError(f"Symbolic links are not supported: {raw_name}")
                planned.append((entry, part))

            output.mkdir(parents=True, exist_ok=True)
            for entry, relative in planned:
                dest = output.joinpath(*relative.parts)
                resolved = dest.resolve()
                if output != resolved and output not in resolved.parents:
                    raise ValueError(f"Archive path escapes destination: {entry.filename}")
                if entry.is_dir():
                    dest.mkdir(parents=True, exist_ok=True)
                else:
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    # Open in exclusive mode so the script never overwrites a file.
                    with dest.open("xb") as handle:
                        handle.write(archive.read(entry))
    except Exception as exc:
        print(f"Extraction failed: {exc}", file=sys.stderr)
        print("If partial files were created in the new output folder, remove that folder and retry.", file=sys.stderr)
        return 4

    file_count = sum(1 for path in output.rglob("*") if path.is_file())
    print("Project rebuilt successfully.")
    print(f"Files written: {file_count}")
    print(f"Location: {output}")
    print("Note: this reconstructs the repository; individual skills/tools still need their documented runtimes and dependencies.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
